contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint256 amount) public payable {
        require(amount > 0);
        require(receiver != address(0));
        // The claimer (this contract) has never deposited, so its unclaimed
        // shares must be zero regardless of parameters.
        uint256 unclaimed = c.unclaimedShares(address(this));
        bool reverted;
        try c.claim(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: claiming a positive amount of shares when the claimer
        // holds zero unclaimed shares always reverts (InsufficientShares).
        assert(reverted && unclaimed == 0);
    }
    receive() external payable {}
}

