contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address receiver, address otherKeeper) public {
        require(amount > 0, "amount must be positive");
        require(receiver != address(0), "receiver must be nonzero");
        require(otherKeeper != address(this), "keeper must differ from test contract");

        // Initialize: this contract acts as glpManager (fallback provides vault()).
        // keeper is set to otherKeeper, so the test contract is NOT the keeper.
        c.initialize(
            IERC20(address(0x02)),
            IERC20(address(0x03)),
            IRewardRouterV2(address(0x04)),
            IGlpManager(address(this)),
            address(0x05),
            otherKeeper
        );

        // Owner (the test contract) reassigns keeper to itself so pauseDeposit is authorized.
        c.setKeeper(address(this));

        // Keeper pauses deposits.
        c.pauseDeposit();

        bool readPausedBefore = c.paused();

        // depositUsdc must revert due to Pausable guard (reverts before any state change).
        bool reverted;
        try c.depositUsdc(amount, receiver) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && readPausedBefore && c.paused());
    }

    fallback(bytes calldata input) external returns (bytes memory) {
        // Serve IGlpManager.vault() so initialize() succeeds.
        input;
        return abi.encode(uint256(1));
    }

    receive() external payable {}
}

