contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint256 amount, uint256 filler) public payable {
        require(receiver != address(1));
        // read current claimable shares for this test contract (fresh state: zero unless setup adds some)
        uint256 claimableBefore = c.unclaimedShares(address(this));
        // optionally top up claimable shares via a claim of filler if available (no-op if 0)
        uint256 available = c.unclaimedShares(address(this));
        bool expectedRevert = (receiver == address(0) || amount == 0 || amount > available);
        bool reverted;
        if (expectedRevert) {
            try c.claim(receiver, amount) { reverted = false; } catch { reverted = true; }
        } else {
            uint256 before = c.unclaimedShares(address(this));
            c.claim(receiver, amount);
            reverted = false;
            uint256 afterShares = c.unclaimedShares(address(this));
            assert(afterShares == before - amount);
        }
        assert(reverted == expectedRevert && claimableBefore == available);
    }
    receive() external payable {}
}

